using System.Security.Cryptography;using System.Text;using Microsoft.Extensions.Options;using Microsoft.Win32;
namespace YoungOne.MediaControl.Agent.Identity;
public sealed class InstallationIdentityStore(IOptions<AgentOptions> options){private static readonly byte[]Entropy=Encoding.UTF8.GetBytes("YoungOne.MediaControl.InstallationIdentity.v1");private readonly string _file=Path.Combine(options.Value.DataDirectory,"identity.dat");public string GetOrCreate(){Directory.CreateDirectory(Path.GetDirectoryName(_file)!);string id;if(File.Exists(_file)){id=Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(_file),Entropy,DataProtectionScope.LocalMachine));if(!Guid.TryParse(id,out _))throw new SecurityException("Invalid protected installation identity");}else{id=Guid.NewGuid().ToString("D");byte[] protectedBytes=ProtectedData.Protect(Encoding.UTF8.GetBytes(id),Entropy,DataProtectionScope.LocalMachine);string temp=_file+".tmp";File.WriteAllBytes(temp,protectedBytes);File.Move(temp,_file,true);}using RegistryKey key=Registry.LocalMachine.CreateSubKey(@"SOFTWARE\YoungOne\MediaControl\Agent",true);string? mirror=key.GetValue("InstallationId")as string;if(mirror is not null&&!StringComparer.OrdinalIgnoreCase.Equals(mirror,id))throw new SecurityException("Installation identity registry mismatch");key.SetValue("InstallationId",id,RegistryValueKind.String);return id;}}
